// Loot Recycle tab for RustyAppraisal.
//
// Breaks modules, ammo, drones and other reprocessable loot into the minerals
// listed in the EVE SDE (recycle-data.js, generated by build-recycle-data.mjs),
// values those minerals with the same live ESI prices as the rest of the tool,
// and compares recycling against selling the loot as-is.

(function () {
    'use strict';

    const DATA_FILE = 'recycle-data.js?v=1';
    const LAST_KEY = 'rustyRecycleLast';

    let recycleData = null;
    let loadingPromise = null;
    let controller = null;
    let lastShare = null;
    let lastCopyText = '';

    function el(id) { return document.getElementById(id); }
    function esc(value) { return typeof escapeHtml === 'function' ? escapeHtml(value) : String(value ?? ''); }
    function num(value) { return typeof fmt === 'function' ? fmt(value) : Number(value).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
    function int(value) { return typeof fmtInt === 'function' ? fmtInt(value) : Number(value).toLocaleString(); }

    function ensureData() {
        if (recycleData) return Promise.resolve(recycleData);
        if (loadingPromise) return loadingPromise;
        loadingPromise = new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = DATA_FILE;
            script.onload = () => {
                if (window.RecycleData && window.RecycleData.types) {
                    recycleData = window.RecycleData;
                    resolve(recycleData);
                } else {
                    loadingPromise = null;
                    reject(new Error('Recycle data is empty.'));
                }
            };
            script.onerror = () => {
                loadingPromise = null;
                reject(new Error('Recycle data failed to load.'));
            };
            document.head.appendChild(script);
        });
        return loadingPromise;
    }

    function getEfficiency() {
        const value = parseFloat(el('recycleEfficiency') ? el('recycleEfficiency').value : '50');
        return Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 50;
    }

    function setEfficiency(value) {
        const input = el('recycleEfficiency');
        if (!input) return;
        const n = parseFloat(value);
        input.value = Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : 50;
    }

    function setProgress(visible, text, percent) {
        const area = el('recycleProgress');
        if (!area) return;
        area.classList.toggle('hidden', !visible);
        if (text) el('recycleProgressText').textContent = text;
        if (percent !== undefined) el('recycleProgressBarFill').style.width = `${Math.max(0, Math.min(100, percent))}%`;
    }

    // Turn pasted lines into per-item reprocessing plans and mineral totals.
    function buildRecycle(lines, efficiency) {
        const rows = [];
        const mineralTotals = new Map();
        const skipped = [];
        const unmatched = [];
        let totalItems = 0;
        let totalBatches = 0;
        let leftoverItems = 0;

        for (const line of lines) {
            const match = typeof matchItem === 'function' ? matchItem(line.name) : null;
            if (!match || match.suggest) {
                unmatched.push(line);
                continue;
            }
            const type = recycleData && recycleData.types ? recycleData.types[match.id] : null;
            if (!type) {
                skipped.push({ name: match.name, qty: line.qty, reason: 'cannot' });
                continue;
            }
            const portion = Math.max(1, Number(type.p) || 1);
            const batches = Math.floor(line.qty / portion);
            if (!batches) {
                skipped.push({ name: match.name, qty: line.qty, reason: 'partial' });
                continue;
            }
            const leftover = line.qty - batches * portion;
            totalItems += line.qty;
            totalBatches += batches;
            leftoverItems += leftover;
            const minerals = type.m
                .map(([id, qty]) => ({
                    id: Number(id),
                    name: (recycleData.names && recycleData.names[id]) || `Type ${id}`,
                    qty: Math.floor((qty * efficiency) / 100) * batches,
                }))
                .filter((mineral) => mineral.qty > 0);
            for (const mineral of minerals) {
                const existing = mineralTotals.get(mineral.id) || { id: mineral.id, name: mineral.name, qty: 0 };
                existing.qty += mineral.qty;
                mineralTotals.set(mineral.id, existing);
            }
            rows.push({
                typeId: match.id,
                name: match.name,
                qty: line.qty,
                portion,
                batches,
                leftover,
                minerals,
            });
        }

        return {
            rows,
            minerals: [...mineralTotals.values()].sort((a, b) => b.qty - a.qty),
            skipped,
            unmatched,
            totalItems,
            totalBatches,
            leftoverItems,
        };
    }

    function priceBasis(price, basis) {
        if (!price) return null;
        if (basis === 'buy') return price.buy !== null && price.buy !== undefined ? price.buy : null;
        if (basis === 'sell') return price.sell !== null && price.sell !== undefined ? price.sell : null;
        if (price.buy !== null && price.buy !== undefined && price.sell !== null && price.sell !== undefined) {
            return (price.buy + price.sell) / 2;
        }
        return price.buy !== null && price.buy !== undefined ? price.buy : (price.sell ?? null);
    }

    function sumBasis(rows, getTotal) {
        const out = { buy: 0, sell: 0, split: 0 };
        let missing = 0;
        for (const row of rows) {
            let counted = false;
            for (const basis of ['buy', 'sell', 'split']) {
                const value = getTotal(row, basis);
                if (value === null) continue;
                out[basis] += value;
                counted = true;
            }
            if (!counted) missing += 1;
        }
        return { ...out, missing };
    }

    function renderRecycle(result, prices, region, efficiency) {
        const mineralRows = result.minerals.map((mineral) => {
            const price = prices.get(mineral.id) || null;
            const buy = price && price.buy !== null && price.buy !== undefined ? price.buy : null;
            const sell = price && price.sell !== null && price.sell !== undefined ? price.sell : null;
            const split = buy !== null && sell !== null ? (buy + sell) / 2 : (buy ?? sell ?? null);
            return {
                ...mineral,
                buy,
                sell,
                split,
                buyTotal: buy !== null ? mineral.qty * buy : null,
                sellTotal: sell !== null ? mineral.qty * sell : null,
                splitTotal: split !== null ? mineral.qty * split : null,
            };
        });

        const mineralTotals = sumBasis(mineralRows, (row, basis) => (
            basis === 'buy' ? row.buyTotal : basis === 'sell' ? row.sellTotal : row.splitTotal
        ));

        // Per item: selling as-is vs recycling into minerals (+ leftover items).
        const itemRows = result.rows.map((row) => {
            const itemPrice = prices.get(row.typeId) || null;
            const rowPrices = {};
            const recycled = {};
            let missing = false;
            for (const basis of ['buy', 'sell', 'split']) {
                const unit = priceBasis(itemPrice, basis);
                const leftoverValue = unit !== null ? row.leftover * unit : (row.leftover ? null : 0);
                let mineralValue = 0;
                for (const mineral of row.minerals) {
                    const mineralPrice = prices.get(mineral.id) || null;
                    const mineralUnit = priceBasis(mineralPrice, basis);
                    if (mineralUnit === null) { missing = true; mineralValue = null; break; }
                    mineralValue += mineral.qty * mineralUnit;
                }
                if (leftoverValue === null) missing = true;
                rowPrices[basis] = unit !== null ? unit * row.qty : null;
                recycled[basis] = mineralValue !== null && leftoverValue !== null
                    ? mineralValue + leftoverValue
                    : null;
            }
            return { ...row, prices: rowPrices, recycled, missing };
        });

        const sellTotals = sumBasis(itemRows, (row, basis) => row.prices[basis]);
        const recycleTotals = sumBasis(itemRows, (row, basis) => row.recycled[basis]);
        const bestTotals = sumBasis(itemRows, (row, basis) => {
            const sell = row.prices[basis];
            const recycle = row.recycled[basis];
            if (sell === null && recycle === null) return null;
            return Math.max(sell ?? 0, recycle ?? 0);
        });

        const pricedCount = mineralRows.filter((row) => row.buy !== null || row.sell !== null).length;

        el('recycleBuyTotal').textContent = num(mineralTotals.buy);
        el('recycleSellTotal').textContent = num(mineralTotals.sell);
        el('recycleSplitTotal').textContent = num(mineralTotals.split);
        el('recycleOutputTotal').textContent = int(result.totalItems);
        el('recycleOutputNote').textContent = `${result.rows.length} item type${result.rows.length === 1 ? '' : 's'} from ${int(result.totalBatches)} reprocessing batch${result.totalBatches === 1 ? '' : 'es'}${result.leftoverItems ? ` · ${int(result.leftoverItems)} left over` : ''}${pricedCount < mineralRows.length ? ` · ${mineralRows.length - pricedCount} unpriced` : ''}`;

        const regionLabel = region === 'all'
            ? 'all trade hubs'
            : (typeof HUB_REGIONS !== 'undefined' && HUB_REGIONS[region] ? HUB_REGIONS[region] : `region ${region}`);
        el('recycleHubNote').textContent = `Recycled at ${efficiency}% efficiency using ${regionLabel} mineral and item prices. ${mineralRows.length} mineral type${mineralRows.length === 1 ? '' : 's'} from ${int(result.totalItems)} items.`;

        const tbody = el('recycleBody');
        tbody.innerHTML = mineralRows.map((row) => `
            <tr>
                <td class="item-cell">
                    <div class="item-cell-inner">
                        <img src="https://images.evetech.net/types/${row.id}/icon?size=32" class="item-icon" alt="" loading="lazy" onerror="this.style.display='none'">
                        <a href="../market/?type=${row.id}&region=${region === 'all' ? 'major' : region}" target="_blank" rel="noopener" class="item-link" title="View ${esc(row.name)} on the Market page">${esc(row.name)}</a>
                    </div>
                </td>
                <td class="num">${int(row.qty)}</td>
                <td class="num price${row.buy !== null ? '' : ' empty'}">${row.buy !== null ? num(row.buy) : '—'}</td>
                <td class="num price${row.sell !== null ? '' : ' empty'}">${row.sell !== null ? num(row.sell) : '—'}</td>
                <td class="num">${row.buyTotal !== null ? num(row.buyTotal) : '—'}</td>
                <td class="num">${row.sellTotal !== null ? num(row.sellTotal) : '—'}</td>
            </tr>`).join('') || '<tr><td colspan="6" class="empty-state">No minerals would be produced at this efficiency.</td></tr>';

        el('recycleFoot').innerHTML = mineralRows.length
            ? `<tr>
                <th>Total</th>
                <th class="num">${int(mineralRows.reduce((sum, row) => sum + row.qty, 0))}</th>
                <th></th>
                <th></th>
                <th class="num">${num(mineralTotals.buy)}</th>
                <th class="num">${num(mineralTotals.sell)}</th>
            </tr>`
            : '';

        // Sell-loot vs recycle comparison (values the loot itself against the minerals).
        el('recycleCompareBody').innerHTML = [
            ['Sell loot as-is', sellTotals],
            ['Recycle into minerals', recycleTotals],
            ['Best per item', bestTotals],
        ].map(([label, totals]) => `
            <tr>
                <td>${esc(label)}</td>
                <td class="num">${num(totals.buy)}</td>
                <td class="num">${num(totals.sell)}</td>
                <td class="num">${num(totals.split)}</td>
            </tr>`).join('');

        const diff = recycleTotals.split - sellTotals.split;
        el('recycleCompareHeadline').textContent = diff > 0
            ? `Recycling is worth ${num(diff)} ISK more than selling everything (split values).`
            : diff < 0
                ? `Selling everything is worth ${num(-diff)} ISK more than recycling (split values).`
                : 'Selling and recycling are worth the same at split values.';

        // Per-item breakdown.
        el('recycleItemBody').innerHTML = itemRows.map((row) => {
            const parts = row.minerals.map((mineral) => `${esc(mineral.name)} ${int(mineral.qty)}`);
            if (row.leftover) parts.push(`${int(row.leftover)} left over`);
            return `
                <tr>
                    <td class="item-cell">
                        <div class="item-cell-inner">
                            <img src="https://images.evetech.net/types/${row.typeId}/icon?size=32" class="item-icon" alt="" loading="lazy" onerror="this.style.display='none'">
                            <span class="item-link">${esc(row.name)}</span>
                        </div>
                    </td>
                    <td class="num">${int(row.qty)}</td>
                    <td class="num">${int(row.batches)}${row.portion > 1 ? ` × ${int(row.portion)}` : ''}</td>
                    <td>${parts.length ? parts.join(' · ') : '—'}</td>
                </tr>`;
        }).join('') || '<tr><td colspan="4" class="empty-state">Nothing was recycled.</td></tr>';

        // Items that cannot be reprocessed or are unknown.
        const notRecycled = [
            ...result.skipped.map((row) => ({
                text: `${row.name} × ${int(row.qty)} — ${row.reason === 'partial' ? 'below one reprocessing batch' : 'cannot be reprocessed'}`,
            })),
            ...result.unmatched.map((row) => ({
                text: `${row.name}${row.qty > 1 ? ` × ${int(row.qty)}` : ''} — not found in the item database`,
            })),
        ];
        const unmatchedWrap = el('recycleUnmatched');
        unmatchedWrap.classList.toggle('hidden', !notRecycled.length);
        if (notRecycled.length) {
            el('recycleUnmatchedNote').textContent = 'These items were not included in the mineral totals. Salvage materials (plates, circuits, consoles and similar) cannot be reprocessed in EVE — sell them on the market instead.';
            el('recycleUnmatchedList').innerHTML = notRecycled
                .map((row) => `<li>${esc(row.text)}</li>`)
                .join('');
        }

        el('recycleResults').classList.remove('hidden');
        el('recycleResults').scrollIntoView({ behavior: 'smooth', block: 'start' });
        return mineralTotals;
    }

    function setRecycleActionsEnabled(enabled) {
        const copy = el('copyRecycleBtn');
        const share = el('shareRecycleBtn');
        if (copy) copy.disabled = !enabled;
        if (share) share.disabled = !enabled;
    }

    async function runRecycle() {
        const lines = typeof parsePaste === 'function' ? parsePaste(el('recycleText').value || '') : [];
        if (!lines.length) {
            showMessage('Paste at least one item to recycle.', 'error');
            return;
        }
        try {
            await ensureData();
        } catch (error) {
            showMessage(error.message || 'Recycle data failed to load.', 'error');
            return;
        }
        const efficiency = getEfficiency();
        const region = el('recycleHubSelect').value || '10000002';
        const result = buildRecycle(lines, efficiency);
        if (!result.rows.length) {
            showMessage(result.unmatched.length
                ? 'None of those items could be matched to the item database.'
                : 'None of those items can be reprocessed.', 'error');
            return;
        }

        const ids = [...new Set([...result.minerals.map((mineral) => mineral.id), ...result.rows.map((row) => row.typeId)])];
        appraisalCancelled = false;
        controller = new AbortController();
        setProgress(true, 'Fetching prices...', 0);
        setRecycleActionsEnabled(false);
        lastShare = null;
        lastCopyText = '';
        try {
            const priceRows = await mapPool(
                ids,
                4,
                (id) => getBestPrices(id, region, controller.signal),
                (done, total) => setProgress(true, `Fetching prices... ${done}/${total}`, (done / total) * 100),
            );
            if (appraisalCancelled) {
                showMessage('Recycle cancelled.', 'error');
                return;
            }
            const prices = new Map(ids.map((id, index) => [id, priceRows[index]]));
            const totals = renderRecycle(result, prices, region, efficiency);
            lastCopyText = `${num(totals.buy)} ISK`;
            lastShare = {
                items: buildShareItems(result),
                efficiency,
                hub: region,
            };
            setRecycleActionsEnabled(true);
            saveLast(el('recycleText').value, region, efficiency);
        } catch (error) {
            if (error && error.name === 'AbortError') {
                showMessage('Recycle cancelled.', 'error');
            } else {
                console.error('Recycle price lookup failed:', error);
                showMessage('Could not fetch market prices. Try again.', 'error');
            }
        } finally {
            controller = null;
            setProgress(false);
        }
    }

    function saveLast(text, hub, efficiency) {
        try {
            localStorage.setItem(LAST_KEY, JSON.stringify({ text, hub, efficiency, ts: Date.now() }));
        } catch (error) { /* ignore storage errors */ }
    }

    function clearRecycle() {
        el('recycleText').value = '';
        el('recycleResults').classList.add('hidden');
        el('recycleCompareHeadline').textContent = '';
        el('recycleCompareBody').innerHTML = '';
        el('recycleBody').innerHTML = '';
        el('recycleFoot').innerHTML = '';
        el('recycleItemBody').innerHTML = '';
        el('recycleUnmatched').classList.add('hidden');
        el('recycleUnmatchedList').innerHTML = '';
        setRecycleActionsEnabled(false);
        lastShare = null;
        lastCopyText = '';
        setProgress(false);
        try { localStorage.removeItem(LAST_KEY); } catch (error) { /* ignore */ }
        el('recycleText').focus();
    }

    function cancelRecycle() {
        appraisalCancelled = true;
        if (controller) controller.abort();
    }

    function buildShareItems(result) {
        const lines = result.rows.map((row) => `${row.qty}:${row.typeId}`);
        for (const row of result.skipped) {
            lines.push(row.qty > 1 ? `${row.qty} x ${row.name}` : row.name);
        }
        for (const row of result.unmatched) {
            lines.push(row.qty > 1 ? `${row.qty} x ${row.name}` : row.name);
        }
        return lines.join('\n');
    }

    function decodeShareItems(items) {
        return String(items || '').split('\n').map((line) => {
            const match = line.trim().match(/^(\d+):(\d+)$/);
            if (match && typeof ItemDB !== 'undefined' && ItemDB && ItemDB.byId) {
                const entry = ItemDB.byId.get(Number(match[2]));
                if (entry) return `${match[1]} x ${entry.name}`;
            }
            return line;
        }).join('\n');
    }

    async function copyText(text) {
        try {
            await navigator.clipboard.writeText(text);
            return true;
        } catch (error) {
            const area = document.createElement('textarea');
            area.value = text;
            document.body.appendChild(area);
            area.select();
            try {
                document.execCommand('copy');
                return true;
            } catch (copyError) {
                return false;
            } finally {
                document.body.removeChild(area);
            }
        }
    }

    async function copyRecycle() {
        if (!lastCopyText) {
            showMessage('Nothing to copy yet.', 'error');
            return;
        }
        if (!await copyText(lastCopyText)) {
            showMessage('Could not copy amount automatically', 'error');
            return;
        }
        showMessage('Amount copied to clipboard', 'success');
    }

    async function shareRecycle() {
        if (!lastShare) {
            showMessage('Calculate a loot recycle first.', 'error');
            return;
        }
        if (typeof API_BASE === 'undefined') {
            showMessage('Share service is unavailable.', 'error');
            return;
        }

        const body = {
            kind: 'recycle',
            items: lastShare.items,
            efficiency: lastShare.efficiency,
        };
        if (lastShare.hub && lastShare.hub !== 'all') body.hub = lastShare.hub;

        try {
            const response = await fetch(`${API_BASE}/appraisal/share`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body),
            });
            const data = await response.json();
            if (!response.ok || !data.code) {
                throw new Error(data.error || `Share failed (${response.status})`);
            }
            const path = location.pathname.replace(/\/index\.html$/, '/');
            const link = `${location.origin}${path}?tab=recycle#${data.code}`;
            if (!await copyText(link)) {
                showMessage('Share link created but clipboard copy failed.', 'error');
                return;
            }
            showMessage('Loot recycle share link copied to clipboard', 'success');
        } catch (error) {
            console.error('Loot recycle share link failed:', error);
            showMessage('Could not create share link. Try again.', 'error');
        }
    }

    function loadRecycleShare(data) {
        if (!data || data.kind !== 'recycle' || !data.items) return;
        if (typeof window.showAppTab === 'function') window.showAppTab('recycle');
        el('recycleText').value = decodeShareItems(data.items);
        if (data.hub && el('recycleHubSelect').querySelector(`option[value="${data.hub}"]`)) {
            el('recycleHubSelect').value = data.hub;
        }
        setEfficiency(data.efficiency);
        setTimeout(runRecycle, 50);
    }

    window.loadRecycleShare = loadRecycleShare;

    function setupTabsHooks() {
        document.addEventListener('apptabchange', (event) => {
            if (event.detail && event.detail.tab === 'recycle') {
                ensureData().catch(() => { /* loaded on demand again */ });
            }
        });
    }

    document.addEventListener('DOMContentLoaded', () => {
        setupTabsHooks();

        el('recycleBtn').addEventListener('click', runRecycle);
        el('clearRecycleBtn').addEventListener('click', clearRecycle);
        el('copyRecycleBtn')?.addEventListener('click', copyRecycle);
        el('shareRecycleBtn')?.addEventListener('click', shareRecycle);
        el('recycleCancelBtn').addEventListener('click', cancelRecycle);

        document.querySelectorAll('[data-recycle-rate]').forEach((button) => {
            button.addEventListener('click', () => setEfficiency(button.dataset.recycleRate));
        });

        el('recycleEfficiency').addEventListener('keydown', (event) => {
            if (event.key === 'Enter') runRecycle();
        });
        el('recycleText').addEventListener('keydown', (event) => {
            if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') runRecycle();
        });

        try {
            const last = JSON.parse(localStorage.getItem(LAST_KEY) || 'null');
            if (last && last.text) {
                el('recycleText').value = last.text;
                if (last.hub && el('recycleHubSelect').querySelector(`option[value="${last.hub}"]`)) {
                    el('recycleHubSelect').value = last.hub;
                }
                if (last.efficiency !== undefined) setEfficiency(last.efficiency);
            }
        } catch (error) { /* ignore corrupt storage */ }

        // ?tab=recycle is opened before this listener ran — warm the data now.
        const panel = el('recycleTab');
        if (panel && !panel.classList.contains('hidden')) {
            ensureData().catch(() => { /* the Calculate button retries */ });
        }
    });
})();
